import type { MetadataRoute } from "next";
import { getTranslations } from "next-intl/server";

import { routing } from "@/core/i18n/routing";

/**
 * Web app manifest. The two colours are deliberate literals: a manifest cannot
 * read CSS variables, so they mirror `--oz-brand` / `--oz-bg` from
 * `src/app/globals.css` (the only other place a hex may appear is `icon.tsx`).
 *
 * TODO(assets): add 192×192 and 512×512 (plus a `maskable`) PNG icons for
 * install prompts — `/icon` is the 32×32 favicon generated by `icon.tsx`.
 */
const BRAND = "#EE3768"; // --oz-brand
const BACKGROUND = "#F4F1EC"; // --oz-bg (light)

export default async function manifest(): Promise<MetadataRoute.Manifest> {
  const t = await getTranslations({
    locale: routing.defaultLocale,
    namespace: "meta",
  });

  return {
    name: "Ozio",
    short_name: "Ozio",
    description: t("home.description"),
    lang: routing.defaultLocale,
    dir: "ltr",
    start_url: "/",
    scope: "/",
    display: "standalone",
    orientation: "portrait",
    background_color: BACKGROUND,
    theme_color: BRAND,
    icons: [
      { src: "/icon", sizes: "32x32", type: "image/png" },
    ],
  };
}
